function checkoutStock(form,service){
 const online=service==='Online';
 const fields=draft.data.lines.map((l,i)=>linkedStockFields(l,i,service)).join('');
 const section=form.querySelector('[data-adjustment]');
 section.innerHTML=fields||'<p>No inventory is linked to the items in this order.</p>';
 section.onchange=e=>{
  const input=e.target;if(!input.matches('[data-stock-select]'))return;
  const row=input.closest('[data-stock-row]'),qty=row.querySelector('[data-stock-amount]');
  qty.disabled=!input.checked;qty.value=input.checked?row.dataset.allocated:0;
 };
 return ()=>{
  for(const row of section.querySelectorAll('[data-stock-row]')){
   const input=row.querySelector('[data-stock-amount]'),line=draft.data.lines[Number(row.closest('[data-stock-index]').dataset.stockIndex)];
   const id=row.dataset.stockRow,qty=input.disabled?0:input.valueAsNumber;
   if(!input.disabled&&!input.checkValidity()){section.hidden=false;form.closest('.pos-dialog118').querySelector('[data-toggle-adjustment]').setAttribute('aria-expanded','true');input.reportValidity();return false}
   const key=online?'onlineStockExtra':'stockUsed';
   line[key]={...line[key],[id]:online?Math.max(0,qty-Number(row.dataset.allocated)):qty};
  }
  return true
 };
}
function pendingStock(id){if(S.sample||S.owner!==offlineOwner())return 0;return S.offlineQueue.filter(e=>e.owner===offlineOwner()&&e.action==='pay'&&!S.stock.some(s=>s.order_id===e.order.id)&&!S.acknowledged125?.includes(e.order.id)).reduce((a,e)=>{try{return a+n((e.data.offlineUsage124||recipeUsage124(e.data))[id])}catch{return a}},0)}
function stock(id){if(S.balances125)return n(S.balances125[id])-pendingStock(id)+(window.kitchen124?.pendingDelta(id)||0);return S.moves.filter(r=>r.data.itemId===id).reduce((a,r)=>a+(['in','adjust-in'].includes(r.data.kind)?1:-1)*n(r.data.quantity),0)-S.stock.filter(r=>r.item_id===id).reduce((a,r)=>a+n(r.quantity),0)-pendingStock(id)+(window.kitchen124?.pendingDelta(id)||0)}
async function rpc(name,args){if(window.posPerformance125)return posPerformance125.rpc(name,args);const out=await ojmDb.rpc(name,args);if(out.error)throw Error(out.error.message);return out.data}
function offlineOwner(){return liveProfile?.id}
async function pending(){S.offlineQueue=await posOffline119.queue(offlineOwner());return S.offlineQueue}
function overlayPending(){for(const entry of S.offlineQueue){const order={...entry.order,offlinePending:true};S.orders=[order,...S.orders.filter(o=>o.id!==order.id)]}}
async function syncPending(){if(S.sample||!navigator.onLine||!offlineOwner())return;const owner=offlineOwner(),epoch=sessionEpoch121,valid=()=>owner===offlineOwner()&&epoch===sessionEpoch121;const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;S.syncError='';for(const entry of entries){if(!valid())return;try{await rpc('pos_order118',{p_id:entry.order.id,p_version:entry.order.version||0,p_action:entry.action,p_data:entry.data});if(!valid())return;await posOffline119.remove(owner,entry.order.id)}catch(e){if(valid())S.syncError='Sync stopped: '+e.message;break}}const left=await posOffline119.queue(owner);if(valid())S.offlineQueue=left}
let loadJob132=null;
function load(options={}){const owner=liveProfile?.id,epoch=sessionEpoch121;if(loadJob132?.owner===owner&&loadJob132.epoch===epoch)return loadJob132.promise;const job={owner,epoch,promise:null};loadJob132=job;job.promise=loadCore132(options).finally(()=>{if(loadJob132===job)loadJob132=null});return job.promise}
async function loadCore132(options={}){if(window.posPerformance125)return posPerformance125.load(S,{catalog,pick,overlayPending},options);if(S.busy||!offlineOwner())return;const owner=offlineOwner(),epoch=sessionEpoch121,valid=()=>owner===offlineOwner()&&epoch===sessionEpoch121;S.busy=true;S.error='';render();try{if(navigator.onLine)await syncPending();if(!valid())return;const data=await rpc('pos_snapshot118',{});if(!valid())return;if(!data||!Array.isArray(data.orders))throw Error('POS database setup is required. Apply the separate v118 POS SQL.');Object.assign(S,data,{loaded:true,owner,offline:false});await posOffline119.saveSnapshot(owner,data);if(!valid())return;navigator.storage?.persist?.().catch(()=>{});const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;overlayPending();const m=menuStore108.state;Object.assign(m,{menu:S.menu,ingredients:S.ingredients,items:S.items,categories:S.categories,moves:[...S.moves,...virtualMoves()],owner,loaded:true});if(!S.picked||!catalog().some(x=>x.id===S.picked))pick(catalog()[0]?.id,false)}catch(e){if(!valid())return;const connectionFailure=(!navigator.onLine||/failed to fetch|networkerror|network request failed|load failed/i.test(e.message))&&!/permission|access required|unauthorized|inactive/i.test(e.message);const cached=connectionFailure?await posOffline119.getSnapshot(owner).catch(()=>null):null;if(!valid())return;if(cached){Object.assign(S,cached.data,{loaded:true,owner,offline:true});const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;overlayPending();if(!S.picked||!catalog().some(x=>x.id===S.picked))pick(catalog()[0]?.id,false);Object.assign(menuStore108.state,{menu:S.menu,ingredients:S.ingredients,items:S.items,categories:S.categories,moves:[...S.moves,...virtualMoves()],owner,loaded:true});S.error='Offline: using the last saved Menu and shift. Sales remain on this device until synced.'}else{S.loaded=false;S.error=connectionFailure?'No offline copy is ready on this device. Connect once while signed in to prepare POS.':e.message;showCenterStatus(S.error,true)}}finally{if(valid()){S.busy=false;render()}}}

function virtualMoves(){return S.stock.map(r=>({id:r.id,created_at:r.created_at,data:{date:r.created_at.slice(0,10),kind:n(r.quantity)>0?'out':'adjust-in',itemId:r.item_id,quantity:Math.abs(n(r.quantity)),reference:'POS '+(S.orders.find(o=>o.id===r.order_id)?.number||r.order_id),note:r.kind==='return'?'Refund restock':'POS sale',pos118:true}}))}
async function task(message,fn){if(S.working)return;const owner=offlineOwner(),epoch=sessionEpoch121;S.working=true;status118.pending(message);try{await fn()}catch(e){if(owner===offlineOwner()&&epoch===sessionEpoch121)showCenterStatus(e.message,true);throw e}finally{if(owner===offlineOwner()&&epoch===sessionEpoch121){S.working=false;render()}}}
function totalsHtml(d){const t=total(d);return `<div class="pos-totals118"><div><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div><span>Discount</span><span>${money(t.discount)}</span></div><div class="total"><span>Total</span><span>${money(t.total)}</span></div></div>`}
const button=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-pos118="${action}" ${attrs}>${label}</button>`;
function orderPanel(order=draft,editable=true){const d=order.data;return `<section class="pos-card118 gold"><header><h2>Current Order</h2><div><strong>${order.offlinePending?'Pending sync':order.number?'#OJ-'+order.number:'New order'}</strong><div class="muted">${esc(d.service)} · ${esc(d.customer||'No table / name')}</div></div></header><div class="pos-order-scroll118">${editable?`<div class="pos-order-meta118"><select aria-label="Order type" data-draft118="service">${['Dine in','Takeaway','Delivery','Online'].map(v=>`<option ${d.service===v?'selected':''}>${v}</option>`).join('')}</select><input aria-label="Table or customer name" placeholder="Table / name" data-draft118="customer" value="${esc(d.customer)}"></div>`:`<span class="status-pill118 ${order.status}">${esc(order.status)}</span> <span class="muted">${time(order.created_at)}</span>`}${d.lines.map((l,i)=>`<div class="pos-line118">${photo(l)}<div><div class="pos-line-name118"><strong>${esc(l.name)}</strong>${editable?button('×','remove','','aria-label="Remove '+esc(l.name)+'" data-index118="'+i+'"'):''}</div><div class="pos-line-values"><span class="pos-amount118">${money(l.unitPrice*l.quantity)}</span>${editable?`<div class="pos-qty118">${button('−','qty','','data-index118="'+i+'" data-delta118="-1" aria-label="Reduce quantity"')}<span>${l.quantity}</span>${button('+','qty','','data-index118="'+i+'" data-delta118="1" aria-label="Increase quantity"')}</div>`:`<span class="muted">Qty ${l.quantity}</span>`}</div><div class="muted">${esc((l.options||[]).join(', '))}${l.note?'<br>'+esc(l.note):''}</div>${editable&&(catalog().find(r=>r.id===l.menuId)?.data.posOptions118||[]).length?button('Edit choices','edit-line','','data-index118="'+i+'"'):''}</div></div>`).join('')||'<p class="muted">Choose a menu item to start this order.</p>'}${editable?`<textarea rows="1" class="pos-order-note118" aria-label="Order note" data-draft118="note" placeholder="Add note (e.g. no onion, extra sauce…)">${esc(d.note)}</textarea><div class="pos-discount118"><span>Discount</span><select data-draft118="discountType" aria-label="Discount type"><option value="percent" ${d.discountType==='percent'?'selected':''}>% Percent</option><option value="amount" ${d.discountType==='amount'?'selected':''}>Amount</option></select><input type="number" min="0" step="any" aria-label="Discount" data-draft118="discount" value="${n(d.discount)}"></div>`:''}</div><div class="pos-order-footer118">${d.promotion146?'<p class="muted">Offer '+esc(d.promotion146.name)+' · '+esc(d.promotion146.code)+'</p>':''}${totalsHtml(d)}<div class="pos-actions118">${editable?button('Save Unpaid','save'):button('▷ Resume Order','resume')}${button('▣ Charge & Print','charge','primary',d.lines.length?'':'disabled')}</div><div class="pos-bottom118">${button(editable?'Receipt preview':'Print Bill','preview')}<span class="muted">Cash · BCEL QR · Bank</span></div>${!editable?`<div class="pos-actions118">${button('Cancel Order','cancel','danger')}</div>`:''}</div></section>`}
function customization(){const d=catalog().find(r=>r.id===S.picked)?.data;if(!d)return '';const price=itemPrice(d);return `<section class="pos-custom118" aria-label="Customize selected item"><header><strong>${esc(d.name)}</strong><span>Base ${money(d.price)}</span></header>${d.description?`<p>${esc(d.description)}</p>`:''}<div class="pos-choices118">${(d.posOptions118||[]).map(g=>{const ids=S.choices[g.id]||[],radio=g.max===1&&g.min===1;return `<fieldset><legend>${esc(g.name)}${g.min?' *':''}</legend><p class="choice-count131">${ids.length} selected · ${g.included!=null?g.included+' included'+(n(g.extraPrice)?' · extra '+money(g.extraPrice)+' each':' · maximum '+g.max):'Choose '+g.min+'–'+g.max}</p><div class="choice-grid131">${g.options.map(o=>{const checked=ids.includes(o.id),available=optionAvailable(o),disabled=!available||(!radio&&!checked&&ids.length>=g.max);return `<label class="choice-tile131 ${checked?'selected':''} ${disabled?'unavailable':''}"><input type="${radio?'radio':'checkbox'}" name="choice-${esc(g.id)}" data-choice118="${esc(g.id)}" value="${esc(o.id)}" ${checked?'checked':''} ${disabled?'disabled':''}><span>${esc(o.name)}${o.price?' +'+fmt(o.price):''}${!available?' · unavailable':''}</span></label>`}).join('')}</div></fieldset>`}).join('')}</div><label class="pos-note131">Preparation note / allergy information<input class="wide" data-item-note118 placeholder="Add a note" value="${esc(S.note)}"></label><footer><div><small>Item total</small><strong aria-live="polite">${money(price)}</strong></div>${button(S.editLine!=null?'Update item':'Add to order','add','primary')}</footer></section>`}

function configureItem(){
 const root=dialog('Order options',customization()),body=root.querySelector('.ui-body108');
 body.oninput=e=>{if(e.target.matches('[data-item-note118]'))S.note=e.target.value};
 body.onchange=e=>{const t=e.target;if(!t.matches('[data-choice118]'))return;const group=t.dataset.choice118;
  S.choices[group]=[...body.querySelectorAll('[data-choice118]:checked')].filter(i=>i.dataset.choice118===group).map(i=>i.value);
  body.innerHTML=customization();body.querySelector('[value="'+CSS.escape(t.value)+'"]')?.focus({preventScroll:true})
 };
 body.onclick=e=>{if(!e.target.closest('[data-pos118="add"]'))return;try{add();root.resolve108(true)}catch(err){showCenterStatus(err.message,true)}};
}
async function menuDetails(id){
 const m=catalog().find(x=>x.id===id);if(!m)return;
 const names=arr=>arr.map(x=>esc(x)).join(', ');
 const norm=name=>String(name).toLowerCase().replace(/^the /,'').replace(/[^a-z0-9]/g,'').replace(/s$/,'');
 function parts(record){
  return (record?.data.recipe||[]).flatMap(r=>{
   const source=(record.data.itemType==='bundle'?S.menu:S.ingredients).find(x=>x.id===r.itemId)?.data;
   return source?[source.name+(Number(r.quantity)>0?' · '+fmt(r.quantity)+' '+(source.unit||'pcs'):'')]:[]
  })
 }
 const sections=(m.worksheetNames||[]).map(g=>{
  const list=g.kind==='components'?g.names.map(name=>{
   const item=S.menu.find(r=>norm(r.data.name)===norm(name));
   const ingredients=parts(item);const detail=ingredients.length?ingredients:[...new Set((item?.worksheetNames||[]).filter(s=>s.kind==='recipe').flatMap(s=>s.names))];
   return '<li><strong>'+esc(name)+'</strong>'+(detail.length?' · '+names(detail):'')+'</li>'
  }).join(''):g.names.map(n=>'<li>'+esc(n)+'</li>').join('');
  return '<section><h4>'+esc(g.kind==='components'?'Combo contents':g.title)+'</h4><ul>'+list+'</ul></section>'
 }).join('');
 const base=parts(m),opts=(m.data.posOptions118||[]).map(g=>'<p><b>'+esc(g.name)+'</b> · '+names(g.options.filter(o=>o.available!==false).map(o=>o.name))+'</p>').join('');
 const picture=photo(m.data);
 const root=dialog(m.data.name,'<div class="pos-customer-menu">'+(picture.includes('<img')?picture:'')+'<div class="pos-customer-recipe"><p><strong>'+money(m.data.price)+'</strong></p>'+(m.data.description?'<p>'+esc(m.data.description)+'</p>':'')+(base.length?'<p><b>Ingredients or components</b> · '+names(base)+'</p>':'')+'<div data-customer-sections>'+sections+'</div>'+opts+(!base.length&&!sections&&!opts?'<p>Ingredient details have not been recorded.</p>':'')+'</div></div>');
 root.querySelector('.pos-dialog118').classList.add('pos-menu-detail-dialog');
 if(!sections||!ojmDb||!navigator.onLine)return;
 const owner=liveProfile?.id,epoch=sessionEpoch121;
 try{
  const result=await ojmDb.from('restaurant_kitchen_worksheets').select('sections').eq('menu_id',m.id).maybeSingle();
  if(result.error||!root.isConnected||liveProfile?.id!==owner||epoch!==sessionEpoch121)return;
  const groups=result.data?.sections;
  if(!groups?.length||groups.some(g=>g.kind==='components'))return;
  root.querySelector('[data-customer-sections]').innerHTML=groups.map(g=>'<section><h4>'+esc(g.title)+'</h4><ul>'+g.rows.map(r=>{
   const portion=[r.quantity!=null?fmt(r.quantity)+' '+(r.unit||''):'',r.note].filter(Boolean).join(' · ');
   return '<li>'+esc(r.name)+(portion?' · '+esc(portion):'')+'</li>'
  }).join('')+'</ul></section>').join('')
 }catch{/* The cashier snapshot already supplies ingredient names offline. */}
}
function tileAction(r){return button('Add','tile-add','pos-tile-add','data-id118="'+esc(r.id)+'"')}
function selectTile(id){
 const menu=$('#pos118 .pos-catalog118');
 if(!menu)return;
 const old=menu.querySelector('.pos-product118.active');
 old?.classList.remove('active');
 old?.parentElement.querySelector('.pos-tile-add')?.remove();
 const tile=menu.querySelector('.pos-product118[data-id118="'+CSS.escape(id)+'"]');
 const record=catalog().find(r=>r.id===id);
 if(tile&&record){
  tile.classList.add('active');
  tile.parentElement.insertAdjacentHTML('beforeend',tileAction(record));
 }
}
function filteredItems(){return catalog().filter(r=>(S.classification==='All'||(S.classification==='Customizable')===!!r.data.posCustom118)&&(S.category==='All'||r.data.category===S.category)&&((r.data.name+' '+r.data.code).toLowerCase().includes(S.query.toLowerCase())))}
function catalogTiles(items){return `${items.slice(0,S.visibleMenu).map(r=>`<div class="pos-menu-tile"><button type="button" class="pos-product118 ${S.picked===r.id?'active':''}" data-pos118="pick" data-id118="${esc(r.id)}">${photo(r.data)}<strong>${esc(r.data.name)}</strong><small>${money(r.data.price)}</small><small>${r.data.posCustom118?'Customize':'Standard'}</small></button>${button('ⓘ','details','pos-info','data-id118="'+esc(r.id)+'" aria-label="Details for '+esc(r.data.name)+'"')}${S.picked===r.id?tileAction(r):''}</div>`).join('')||'<p>No matching items.</p>'}`}
function refreshCatalog(){
 const grid=$('#pos118 .pos-catalog118');
 if(!grid)return;
 const items=filteredItems();
 grid.innerHTML=catalogTiles(items);
 grid.parentElement.querySelector('[data-pos118="more-menu"]')?.remove();
 if(items.length>S.visibleMenu)grid.insertAdjacentHTML('afterend',button('Show more menu items','more-menu'));
 for(const filter of grid.parentElement.querySelectorAll('[data-pos118="classification"],[data-pos118="category"]')){
  filter.classList.toggle('active',S[filter.dataset.pos118]===filter.dataset.value118);
 }
}
function newOrder(){const items=filteredItems();return `<div class="pos-grid118"><section class="pos-card118"><div class="pos-filter118"><input data-search118 placeholder="Search menu name or code…" aria-label="Search menu" value="${esc(S.query)}"><div class="pos-pills118">${['All','Standard','Customizable'].map(c=>button(c,'classification',S.classification===c?'active':'','data-value118="'+c+'"')).join('')}</div><div class="pos-pills118">${['All',...new Set(catalog().map(r=>r.data.category||'Other'))].map(c=>button(esc(categoryName(c)),'category',S.category===c?'active':'','data-value118="'+esc(c)+'"')).join('')}</div></div><div class="pos-catalog118">${catalogTiles(items)}</div>${items.length>S.visibleMenu?button('Show more menu items','more-menu'):''}</section>${orderPanel()}</div>`}
function selectedOrder(){return S.orders.find(o=>o.id===S.selected)}
function openOrders(online=false){const orders=S.orders.filter(o=>o.status==='unpaid'&&(!online||o.data.service==='Online')&&(S.filter==='All'||o.data.service===S.filter)&&JSON.stringify([o.number,o.data.customer]).toLowerCase().includes(S.query.toLowerCase()));const selected=orders.find(o=>o.id===S.selected)||orders[0];if(selected)S.selected=selected.id;return `<div class="pos-grid118"><section class="pos-card118"><header><h2>${online?'Online Orders':'Open Orders'}</h2><input data-search118 placeholder="Search order, table or name…" aria-label="Search orders" value="${esc(S.query)}"></header>${online?'<p class="muted">Promotion orders are available in Offer orders. Other messaging orders are entered manually.</p>':''}<div class="pos-pills118">${['All','Dine in','Takeaway','Delivery','Online'].map(v=>button(v,'filter',S.filter===v?'active':'','data-value118="'+v+'"')).join('')}</div><table><thead><tr>${['Order','Table / Name','Time','Items','Total','Status'].map(v=>'<th>'+v+'</th>').join('')}</tr></thead><tbody>${orders.slice(0,S.visibleOrders).map(o=>`<tr data-order118="${o.id}" class="${o===selected?'selected':''}" tabindex="0"><td>OJ-${o.number}</td><td>${esc(o.data.customer||o.data.service)}</td><td>${time(o.created_at)}</td><td>${o.data.lines.reduce((a,l)=>a+n(l.quantity),0)}</td><td>${money(o.data.total)}</td><td><span class="status-pill118 unpaid">Unpaid</span></td></tr>`).join('')||'<tr><td colspan="6">No open orders.</td></tr>'}</tbody></table><div class="pos-table-footer118">${orders.length} open orders · ${money(orders.reduce((a,o)=>a+n(o.data.total),0))}${orders.length>S.visibleOrders?button('Show more','more'):''}</div></section>${selected?orderPanel(selected,false):'<section class="pos-card118"><h2>Current Order</h2><p>Select or start an order.</p>'+button('New Order','new','primary')+'</section>'}</div>`}
function paperWidth(){return Number(S.config.receiptWidth)===58?58:80}
function receipt(o,kitchen=false,checkout=false){const d=o.data,t=checkout||d.total==null?total(d):{subtotal:d.subtotal,discount:d.discount,total:d.total};const printedAt=checkout?new Date():o.paid_at||o.created_at||new Date();return `<article class="receipt118" style="--receipt-width:${paperWidth()}mm"><header><img src="assets/brand/oonjai-logo.png" alt="Oon Jai Marketplace"><h3>${kitchen?'Kitchen ticket':'Oon Jai Marketplace'}</h3>${S.sample?'<strong>SAMPLE · NOT A SALE</strong>':o.offlinePending?'<strong>LOCAL COPY · PENDING SYNC</strong>':''}</header><hr><div class="receipt-row118 receipt-meta"><span>${date(printedAt)} ${time(printedAt)}</span><span>${o.offlinePending?'Number pending sync':o.number?esc(checkout||['paid','refunded'].includes(o.status)?posReports.receiptId(o.number):'OJ-'+o.number):'Number assigned on payment'}</span></div><div>${esc(d.service)} · ${esc(d.customer)}</div><div>Cashier: ${esc(d.cashier||currentUser())}</div><hr>${d.lines.map(l=>`<div class="receipt-row118"><strong>${l.quantity} × ${esc(l.name)}</strong>${kitchen?'':'<span>'+fmt(l.quantity*l.unitPrice)+'</span>'}</div>${l.options?.length?'<div>+ '+esc(l.options.join(', '))+'</div>':''}${l.note?'<div><b>Note:</b> '+esc(l.note)+'</div>':''}`).join('')}${d.note?'<p><b>Order note:</b> '+esc(d.note)+'</p>':''}${d.promotion146?'<p>Offer: '+esc(d.promotion146.name)+'<br>Reference: '+esc(d.promotion146.code)+(d.promotion146.voucher?'<br>Voucher: '+esc(d.promotion146.voucher):'')+'</p>':''}${kitchen?'':`<hr><div class="receipt-row118"><span>Subtotal</span><span>${fmt(t.subtotal)}</span></div><div class="receipt-row118"><span>Discount</span><span>${fmt(t.discount)}</span></div><hr><div class="receipt-row118"><strong>TOTAL</strong><strong>${money(t.total)}</strong></div><hr><div>${o.status==='refunded'?'REFUNDED':o.status==='paid'?'Paid: '+esc(d.payment):checkout?'':'UNPAID'}</div>${d.paymentReference?'<div>Reference: '+esc(d.paymentReference)+'</div>':''}<p class="receipt-foot118">${esc(S.config.receiptFooter)}</p>`}</article>`}
